function returnsView(d){const rows=(d||[]).map(r=>`<tr><td><b>${esc(r.return_no)}</b></td><td>${esc(r.order_no||r.sale_no||'—')}</td><td>${esc(r.customer_name||'Guest')}</td><td>${money(r.refund_amount)}</td><td>${pill(r.status)}</td><td>${new Date(r.created_at).toLocaleString()}</td><td>${btn('Open','return-open:'+r.id)}</td></tr>`);return `<div class="hero"><div class="kicker">Returns & Refunds</div><h2 style="margin:6px 0">Returns control</h2><p class="muted">Approve, receive, inspect, refund and restock returned products with a complete history.</p></div><div class="toolbar">${has('returns.manage')?btn('New return','return-create','btn primary'):''}</div>${table(['Return','Source','Customer','Amount','Status','Created','Actions'],rows,'No returns','Create a return request against an order or sale.')}`}
function documentsView(d){const rows=(d||[]).map(r=>`<tr><td><b>${esc(r.name)}</b><br><span class="muted">v${num(r.version_no)} · ${esc(r.mime_type)} · ${num((Number(r.size_bytes)||0)/1024/1024)} MB</span></td><td>${esc(r.entity_type)}<br><span class="muted">${esc(r.entity_id||'General')}</span></td><td>${pill(r.visibility)} ${pill(r.status)}<br><span class="muted">${r.expires_at?'Expires '+new Date(r.expires_at).toLocaleDateString():'No expiry'}</span></td><td>${r.verified_at?'Verified':'Unverified'}</td><td>${esc(r.created_by_name||'—')}<br>${new Date(r.created_at).toLocaleString()}</td><td>${has('documents.download')?btn('Download','document-download:'+r.id):''}${has('documents.manage')?btn('Details','document-details:'+r.id):''}${has('documents.manage')?btn('New version','document-version:'+r.id):''}${has('documents.manage')&&!r.verified_at?btn('Verify','document-verify:'+r.id):''}${has('documents.manage')&&r.status!=='Archived'?btn('Archive','document-delete:'+r.id):''}</td></tr>`);return `<div class="hero"><div class="kicker">Document Management</div><h2 style="margin:6px 0">Documents</h2><p class="muted">Controlled document storage with entity attachment, version history, verification, expiry, retention and audit history.</p></div><div class="toolbar">${has('documents.manage')?btn('Upload document','document-upload','btn primary'):''}</div>${table(['File','Record','Access & lifecycle','Verification','Uploaded','Actions'],rows,'No documents','Upload a document to keep it inside the platform.')}`}
const priorOpsLoad=load;
load=async function(v){if(v==='Delivery & Logistics'){state.loading=true;try{state.data={summary:await api('/delivery/summary'),shipments:await api('/delivery/shipments'),zones:await api('/delivery/zones'),partners:await api('/delivery/partners')};renderView();}catch(e){state.error=e.message;renderView()}finally{state.loading=false;flash()}return;}if(v==='Warranty & Repairs'){state.loading=true;try{state.data={claims:await api('/warranty/claims'),policies:await api('/warranty/policies'),partners:await api('/warranty/partners')};renderView();}catch(e){state.error=e.message;renderView()}finally{state.loading=false;flash()}return;}if(v==='Returns & Refunds'){state.loading=true;try{state.data=await api('/returns');renderView();}catch(e){state.error=e.message;renderView()}finally{state.loading=false;flash()}return;}if(v==='Documents'){state.loading=true;try{state.data=await api('/documents?limit=300');renderView();}catch(e){state.error=e.message;renderView()}finally{state.loading=false;flash()}return;}return priorOpsLoad(v)};
renderView=function(){if(['Delivery & Logistics','Warranty & Repairs','Returns & Refunds','Documents'].includes(state.view)){const c=$('#content');if(!c)return;c.innerHTML=state.view==='Delivery & Logistics'?deliveryView(state.data):state.view==='Warranty & Repairs'?warrantyView(state.data):state.view==='Returns & Refunds'?returnsView(state.data):documentsView(state.data);bindView();flash();return;}return priorRenderView912()};
