      if(a==='credit-link-sale')return formModal('Link sale to credit',[field('Sale ID','sourceId','','text','required'),field('Term months','termMonths','6','number','min="1" required')],x=>api('/credit/from-sale',{method:'POST',body:JSON.stringify({...x,termMonths:Number(x.termMonths)})}),'Create credit account');
