      if(a.startsWith('credit-profile-edit:')){const id=a.split(':')[1],d=(await api('/credit/profiles')).find(x=>x.id===id);return formModal('Edit credit profile',[field('Customer ID','customerId',d.customer_id),field('Credit limit (UGX)','creditLimit',d.credit_limit,'number','min="0"'),field('Risk grade','riskGrade',d.risk_grade),select('Status','status',d.status,[['Active','Active'],['Suspended','Suspended'],['Closed','Closed']]),area('Notes','notes',d.notes)],x=>api('/credit/profiles',{method:'POST',body:JSON.stringify({...x,creditLimit:Number(x.creditLimit)})}),'Save profile')}
