      if(a.startsWith('credit-decision:')){const d=(await api('/credit/applications')).find(x=>x.id===a.split(':')[1]);return formModal('Review credit application',[select('Decision','status','Approved',[['Approved','Approve'],['Rejected','Reject'],['Cancelled','Cancel']]),field('Approved amount','approvedAmount',d.requested_amount,'number','min="1"'),field('Down payment','downPayment',d.down_payment,'number','min="0"'),field('Term months','termMonths',d.term_months,'number','min="1"'),area('Decision note','note')],x=>api('/credit/applications/'+d.id+'/decision',{method:'POST',body:JSON.stringify({...x,approvedAmount:Number(x.approvedAmount),downPayment:Number(x.downPayment),termMonths:Number(x.termMonths)})}),'Record decision')}
      if(a.startsWith('credit-account:')){const d=await api('/credit/accounts/'+a.split(':')[1]);return modal('Credit account',`<div class="grid2"><div class="card"><b>${esc(d.account.account_no)}</b><p>${esc(d.account.customer_name)}</p><p>${pill(d.account.status)}</p><div class="statline"><span>Outstanding</span><b>${money(d.account.outstanding_principal)}</b></div></div><div class="card"><b>Installment schedule</b>${table(['#','Due','Principal','Paid','Status'],d.installments.map(x=>`<tr><td>${num(x.installment_no)}</td><td>${esc(String(x.due_date).slice(0,10))}</td><td>${money(x.principal_due)}</td><td>${money(x.paid_amount)}</td><td>${pill(x.status)}</td></tr>`),'No installments','')}</div></div>${table(['Receipt','Amount','Method','Reference','Date'],d.payments.map(x=>`<tr><td>${esc(x.receipt_no)}</td><td>${money(x.amount)}</td><td>${esc(x.method)}</td><td>${esc(x.reference||'—')}</td><td>${new Date(x.paid_at).toLocaleString()}${has('credit.approve')?` ${btn('Reverse','credit-payment-reverse:'+d.account.id+':'+x.id)}`:''}</td></tr>`),'No payments','')}${d.links?.length?`<div class="card"><b>Operational links</b>${d.links.map(x=>`<div class="statline"><span>${esc(x.source_type)}</span><b>${esc(x.source_id)}</b></div>`).join('')}</div>`:''}`)}
      if(a.startsWith('credit-payment-reverse:')){const p=a.split(':');return formModal('Reverse credit payment',[area('Reason','reason','','required')],x=>api('/credit/accounts/'+p[1]+'/payment/'+p[2]+'/reverse',{method:'POST',body:JSON.stringify(x)}),'Reverse payment')}
      if(a.startsWith('credit-payment:')){const id=a.split(':')[1];return formModal('Record credit payment',[field('Amount (UGX)','amount','','number','min="1" required'),select('Method','method','Cash',['Cash','Mobile Money','Card','Bank Transfer'].map(x=>[x,x])),field('Reference','reference')],x=>api('/credit/accounts/'+id+'/payment',{method:'POST',body:JSON.stringify({...x,amount:Number(x.amount)})}),'Record payment')}
      if(a.startsWith('credit-restructure:')){const id=a.split(':')[1];return formModal('Restructure credit',[field('New term months','termMonths','6','number','min="1"'),area('Reason','reason','','required')],x=>api('/credit/accounts/'+id+'/restructure',{method:'POST',body:JSON.stringify({termMonths:Number(x.termMonths),reason:x.reason})}),'Approve restructure')}
