      if(a.startsWith('finance-journal:')){const d=await api('/finance/journals/'+a.split(':')[1]);return modal('Journal '+d.journal.journal_no,`<p><b>${esc(d.journal.description)}</b> · ${esc(d.journal.source_type)}</p>${table(['Account','Description','Debit','Credit'],d.lines.map(x=>`<tr><td>${esc(x.code)} — ${esc(x.account_name)}</td><td>${esc(x.description)}</td><td>${money(x.debit)}</td><td>${money(x.credit)}</td></tr>`),'No lines','')}`)}
